package bo.com.ganadero.sanidad.api;
import bo.com.ganadero.sanidad.application.ClinicaService;import bo.com.ganadero.sanidad.domain.AplicacionTratamiento;import bo.com.ganadero.shared.api.ApiResponse;import bo.com.ganadero.shared.web.CorrelationIdFilter;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.UUID;
/** Endpoint operativo corto especificado para la PWA. */
@RestController @RequestMapping("/api/v1/tratamientos") public class AplicacionTratamientoController{private final ClinicaService service;public AplicacionTratamientoController(ClinicaService s){service=s;}@PostMapping("/{tratamientoId}/aplicaciones/{aplicacionId}/aplicar")ApiResponse<AplicacionTratamiento>aplicar(@PathVariable UUID tratamientoId,@PathVariable UUID aplicacionId,@Valid@RequestBody AplicarTratamientoRequest b,HttpServletRequest r){Object c=r.getAttribute(CorrelationIdFilter.ATTRIBUTE);return ApiResponse.success(service.aplicar(tratamientoId,aplicacionId,b.command()),c==null?"unknown":c.toString());}}
